// TaskStatus is where a task stands.
type TaskStatus int32

const (
	// Not set.
	TaskStatus_TASK_STATUS_UNSPECIFIED TaskStatus = 0
	// Planned, not started.
	TaskStatus_TASK_STATUS_PENDING TaskStatus = 1
	// A worker is on it.
	TaskStatus_TASK_STATUS_RUNNING TaskStatus = 2
	// Finished.
	TaskStatus_TASK_STATUS_DONE TaskStatus = 3
	// Stopped on an error.
	TaskStatus_TASK_STATUS_FAILED TaskStatus = 4
	// Stopped on request.
	TaskStatus_TASK_STATUS_STOPPED TaskStatus = 5
	// Cut short because djinn up stopped or crashed while its worker ran. The task keeps its provider, session and
	// worktree; the next djinn up resumes it (RESUMING) unless it cannot: imported, its worktree gone, its wish
	// granted, or already resumed as another task (Task.fork_of).
	TaskStatus_TASK_STATUS_INTERRUPTED TaskStatus = 6
	// Its worker ended its turn, and the task waits for an answer, without a worker and without a slot of the machine:
	// read-only, to its edit question (Task.edit_question_id), where a yes starts the worker again, allowed to edit the
	// project's files; or to the blocking question its worker asked (Task.wait_question_id), where the answer continues
	// it with the decision once a slot is free. Its worktree, branch, session and write scopes stay.
	TaskStatus_TASK_STATUS_WAITING TaskStatus = 7
	// Its worker holds still on request, without losing anything, until it is resumed. It takes no slot of the
	// machine meanwhile.
	TaskStatus_TASK_STATUS_PAUSED TaskStatus = 8
	// Djinn resumes its worker by itself, in the same task, worktree and session: djinn up restarted while it ran, or
	// its provider's usage limit stopped it. The scheduler starts it again like a planned task, first, once
	// Task.resume_after has passed. Not the person's move.
	TaskStatus_TASK_STATUS_RESUMING TaskStatus = 9
	// Cancelled: its worker was stopped, its worktree removed, and its work discarded.
	TaskStatus_TASK_STATUS_CANCELLED TaskStatus = 10
)

